const defaultFruitSuggestions = [
  'Apple',
  'Apricot',
  'Avocado',
  'Banana',
  'Blueberry',
  'Cherry',
  'Cranberry',
  'Date',
  'Elderberry',
  'Fig',
  'Grape',
];

function Demo() {
  const {
    delay = 100,
    suggestions = defaultFruitSuggestions,
    onSelect,
  } = usePreviewProps({
    delay: 100,
    suggestions: defaultFruitSuggestions,
  });

  const fetchSuggestions = async (q) => {
