const Accordion = ({ items, allowMultiple = false }) => {
  const [open, setOpen] = useState([]);
  const base = useId();

  const toggle = (id) => {
    setOpen((current) => {
      if (current.includes(id)) return current.filter((x) => x !== id);
      return allowMultiple ? [...current, id] : [id];
    });
  };

  return (
    <div>
      {items.map((item) => {
        const isOpen = open.includes(item.id);
