    if (e.key === 'ArrowRight') step(1);
    if (e.key === 'ArrowLeft') step(-1);
  };

  return (
    <section aria-roledescription="carousel" aria-label="Gallery" tabIndex={0} onKeyDown={onKeyDown}>
