  if (checkedCount === 0 && !hasIndeterminate) return 'unchecked';
  return 'indeterminate';
};

const useCheckboxTree = (
  treeData: TreeNode[],
  initialChecked: string[] = []
): {
  checkedIds: string[];
  getStatus: (id: string) => CheckboxStatus;
