          </button>
        )}
        {canReply && (
          <button
            type="button"
            data-action="reply"
            onClick={() => setReplying(!replying)}
          >
            Reply
          </button>
        )}
      </div>

      {replying && (
        <div>
          <textarea
            data-reply-input
            placeholder="Write a reply..."
            value={replyText}
            onChange={(e) => setReplyText(e.target.value)}
          />
          <div>
            <button
              type="button"
              data-action="submit-reply"
              onClick={handleSubmitReply}
            >
              Submit
            </button>
            <button
              type="button"
              data-action="cancel-reply"
              onClick={() => {
                setReplyText('');
                setReplying(false);
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {hasChildren && !collapsed && (
        <ul>
          {comment.children.map((child) => (
            <CommentNode
              key={child.id}
              comment={child}
              onAddReply={onAddReply}
              maxDepth={maxDepth}
              depth={depth + 1}
            />
          ))}
        </ul>
      )}
    </li>
  );
}

const NestedComments = ({ comments, onAddReply, maxDepth = 4 }) => {
  return (
