const defaultColumns = [
  {
    id: 'todo',
    title: 'To Do',
    cards: [
      { id: 't1', title: 'Implement Auth Flow', description: 'JWT tokens and refresh flow' },
      { id: 't2', title: 'Cache Strategy', description: 'Configure Redis cache layers' },
